<?php
require_once dirname(__DIR__, 1) . '/includes/bootstrap.php';
$user = require_role('CUSTOMER');
require_once dirname(__DIR__, 1) . '/app/Customers/CustomerPortalService.php';
$portal = new CustomerPortalService(db(), (int) $user['user_id']);
$profile = $portal->profile();
$products = $portal->products();
$state = take_form('loan_request');
$input = $state['input'] ?? [];
$input['product_id'] ??= (string) (int) ($_GET['product'] ?? 0);
$_SESSION['loan_request_token'] ??= bin2hex(random_bytes(32));
$title = t('Explore loans');
require dirname(__DIR__, 1) . '/includes/header.php';
?>
<div class="page-heading"><div><span class="eyebrow"><?= e(t('For whatever comes next')) ?></span><h1><?= e(t('A loan for your next move.')) ?></h1><p><?= e(t('Explore your options. Choose your terms. Put your plans in motion.')) ?></p></div></div>
<div class="product-grid"><?php foreach ($products as $product): ?><article class="card product-tile"><div class="section-heading"><span class="product-symbol">↗</span><span class="count-pill"><?= $product['requires_collateral'] ? t('Collateral required') : t('No collateral') ?></span></div><h2><?= e($product['product_name']) ?></h2><p class="muted"><?= e($product['description']) ?></p><div class="product-rate"><?= e(format_number($product['interest_rate_pct'], 2)) ?><small><?= e(t('% flat interest, applied once')) ?></small></div><dl class="detail-list"><div><dt><?= e(t('Amount range')) ?></dt><dd><?= e(format_number((float)$product['min_amount_rwf'])) ?> – <?= e(format_number((float)$product['max_amount_rwf'])) ?> RWF</dd></div><div><dt><?= e(t('Repayment term')) ?></dt><dd><?= e(t('Up to')) ?> <?= e($product['max_term_months']) ?> <?= e(t('months')) ?></dd></div></dl><a class="button secondary wide" href="<?= e(app_url('requestLoan.php?product=' . $product['product_id'] . '#application')) ?>"><?= e(t('Choose this loan ↗')) ?></a></article><?php endforeach; ?></div>
<?php if (!$products): ?><section class="card empty"><h2><?= e(t('No loan products are available yet.')) ?></h2><p><?= e(t('Contact your lending firm for information about upcoming products.')) ?></p></section><?php endif; ?>
<section class="card spaced application-form-card" id="application"><div class="section-heading"><div><span class="eyebrow"><?= e(t('Let’s make it happen')) ?></span><h2><?= e(t('Your loan application')) ?></h2></div><span class="count-pill"><?= e(t('01 / Apply')) ?></span></div>
<?php if (!empty($state['errors'])): ?><div class="notice error" role="alert"><?php foreach ($state['errors'] as $error): ?><div><?= e(t($error)) ?></div><?php endforeach; ?></div><?php endif; ?>
<?php if (!CustomerPortalService::canRequest($profile)): ?><div class="notice"><h3><?= e(t('Your profile needs attention.')) ?></h3><p><?= e(t('Your firm needs to approve your national ID and proof of income before you can request a loan.')) ?></p><p><?= e(t('Customer verification:')) ?> <?= e($profile ? status_label($profile['kyc_status']) : t('Profile not linked')) ?> <?= e(t('· Firm:')) ?> <?= e($profile['firm_name'] ?? t('Not assigned')) ?></p><a class="button" href="<?= e(app_url('portal/documents.php')) ?>"><?= e(t('Complete your documents →')) ?></a></div>
<?php elseif ($products): ?><form method="POST" action="<?= e(app_url('loan.php')) ?>"><?= csrf_field() ?><input type="hidden" name="request_token" value="<?= e($_SESSION['loan_request_token']) ?>"><div class="field"><label for="product"><?= e(t('Loan product')) ?></label><select id="product" name="product_id" data-product-select required><option value=""><?= e(t('Choose a loan product')) ?></option><?php foreach ($products as $product): ?><option value="<?= e($product['product_id']) ?>" data-rate="<?= e($product['interest_rate_pct']) ?>" data-min="<?= e($product['min_amount_rwf']) ?>" data-max="<?= e($product['max_amount_rwf']) ?>" data-term="<?= e($product['max_term_months']) ?>" <?= (string)$input['product_id']===(string)$product['product_id'] ? 'selected' : '' ?>><?= e($product['product_name']) ?></option><?php endforeach; ?></select><p class="help" data-product-hint><?= e(t('Choose a product to see its amount range and terms.')) ?></p></div><div class="row"><div class="field"><label for="amount"><?= e(t('Amount requested (RWF)')) ?></label><input id="amount" name="amount_requested_rwf" type="number" min="0.01" max="999999999999.99" step="0.01" inputmode="decimal" value="<?= e($input['amount_requested_rwf'] ?? '') ?>" required></div><div class="field"><label for="term"><?= e(t('Repayment term (months)')) ?></label><input id="term" name="term_months" type="number" min="1" max="255" step="1" value="<?= e($input['term_months'] ?? '') ?>" required></div></div><div class="field"><label for="purpose"><?= e(t('What will you use the loan for?')) ?></label><textarea id="purpose" name="purpose" maxlength="255" placeholder="<?= e(t('Tell us about your plans…')) ?>" required><?= e($input['purpose'] ?? '') ?></textarea></div><div class="estimate-box" data-estimate><?= e(t('Enter an amount and term to see an estimate.')) ?></div><p class="help"><?= e(t('Your manager will review your application. Final approval, terms, and disbursement depend on your firm’s decision. Products 